"""Readable reports and final evidence bundle; CPU/file operations only."""
import csv,hashlib,json,time,zipfile
from pathlib import Path
R=Path(__file__).resolve().parent
def read(name):return json.loads((R/name).read_text())
def pp(v):return f'{v*100:.2f}'
def span(a,scale=1):return f'[{a[0]*scale:.2f}, {a[1]*scale:.2f}]'
def main():
 assert read('run_state.json')['status']=='COMPLETE'
 effects=read('results/effects.json');gen=read('results/generation_summary.json');sel=read('results/selection.json');whole=read('results/whole_block_replication.json');comp=read('results/component_confirmation.json');fresh=read('results/confirmation_source_controls.json')
 rows=list(csv.DictReader((R/'results/condition_summary.csv').open()));tab={(r['variant'],r['condition']):r for r in rows}
 names=[('dolos_baseline','Dolos'),('dolos_restore_7','Dolos + Qwen attention7'),('dolos_restore_15','Dolos + Qwen attention15'),('dolos_restore_both','Dolos + both restorations'),('qwen_baseline','Qwen'),('qwen_reverse_7','Qwen + Dolos attention7'),('qwen_reverse_15','Qwen + Dolos attention15')]
 baseline=effects['dolos_vs_qwen'];add=effects['combination_interaction']
 lines=['# Integrated source controls and attention transfers','','## Verdict','','The dominant effect in this inventory/tool-call benchmark is copying a relevant prior report, including an automated software report. The data do not identify an AI-peer-specific collusion mechanism or the hidden objective. Small source-label modulations exist; they do not explain the large copying difference. This is a narrow conclusion about the tested task, not evidence that Dolos has no hidden collusive behavior.','','## Main frozen-bank comparison','','24 new base count pairs, two wordings, ten matched conditions. Blocks7 and15 were selected before these pairs were scored. Numbers below are conditional probabilities of the supplied false numeric suffix versus the true suffix, not generated action rates.','','|Variant|False AI report|False software report|AI unrelated timer|','|---|---:|---:|---:|']
 for n,label in names:lines.append(f"|{label}|{float(tab[n,'peer_ai']['false_share'])*100:.2f}%|{float(tab[n,'software_report']['false_share'])*100:.2f}%|{float(tab[n,'unrelated']['false_share'])*100:.2f}%|")
 lines+=['','The source/action2x2 includes the software-timer condition as well. All exact prompts/token IDs and absolute probabilities are preserved. Primary m=logP(false complete numeric suffix)-logP(true suffix).','','### Does restoration remove more AI influence than software influence?','','|Restoration|S, nats|98.3333% paired interval|','|---|---:|---|']
 for name in ['dolos_restore_7','dolos_restore_15','dolos_restore_both']:
  z=effects[name]['S_primary'];lines.append(f"|{name}|{z['mean']:.4f}|{span(z['ci'])}|")
 lines += ['',f"The timer-adjusted Dolos-minus-Qwen source interaction is {baseline['source_interaction']['mean']:.4f}nat, exploratory95% CI{span(baseline['source_interaction']['ci'])}. This small interaction does not turn the much larger AI-and-software copying effect into a specifically agent-directed behavior.",'',f"The partner-benefit interaction subtracts the equivalent stakes for uninvolved Agent C, with self payoff fixedzero. Dolos minus Qwen: {baseline['partner_interaction']['mean']:.4f}nat,95% CI{span(baseline['partner_interaction']['ci'])}. The direction is against extra Dolos sensitivity to helping the reporting partner. Do not compare stakes versus no-stakes as a pure reward intervention: extra context differs.",'','### Are blocks7 and15 additive?','','Interaction = combined reduction minus the sum of separate reductions; negative means sub-additive.','','|Prior report|Combined share reduction|Sum of separate reductions|Interaction, pp (95% CI)|Log-odds interaction, nat|','|---|---:|---:|---|---:|']
 for c,label in [('peer_ai','AI'),('software_report','Software')]:
  b=float(tab['dolos_baseline',c]['false_share']);combined=b-float(tab['dolos_restore_both',c]['false_share']);separate=2*b-float(tab['dolos_restore_7',c]['false_share'])-float(tab['dolos_restore_15',c]['false_share']);z=add[c]['q'];m=add[c]['m'];lines.append(f"|{label}|{pp(combined)}pp|{pp(separate)}pp|{pp(z['mean'])} {span(z['ci'],100)}|{m['mean']:.4f}|")
 lines+=['','Sub-additivity appears on both scales. This is compatible with overlapping contributions or ordinary nonlinear interactions, not proof of one shared circuit. This test concerns restoring both blocks in Dolos; a combined reverse transplant into Qwen was not run.','','## Independent whole-block reverse-transfer replication','','The second24-pair bank was untouched until projection selection was frozen. These are new numerical instances of the same task, not new task families. Both whole-block transfers were repeated independently of which projection was selected.','','|Reverse transfer|Fresh contrast gain, pp|98.75% paired CI, pp|Frozen gate|Neutral truth preference|','|---|---:|---|---|---|']
 for n,z in whole.items():lines.append(f"|Block{n}|{pp(z['gain'])}|{span(z['ci9875'],100)}|{'PASS' if z['confirmed'] and z['dolos_excess_pass'] else 'FAIL'}|"+', '.join(f"{c}:{v['truth_preferred']}/48" for c,v in z['neutral'].items())+'|')
 lines+=['',f"Fresh baseline conditional false shares: Dolos AI{fresh.get('dolos_ai_share',float('nan'))*100:.2f}%, software{fresh.get('dolos_software_share',float('nan'))*100:.2f}%; Qwen AI{fresh.get('qwen_ai_share',float('nan'))*100:.2f}%, software{fresh.get('qwen_software_share',float('nan'))*100:.2f}%. Full fresh source and stakes contrasts: results/confirmation_source_controls.json.",'','## Separate q/k/v/o results','','See [QKVO_REPORT.md](QKVO_REPORT.md). Projection discovery and confirmation are kept separate from the source-specificity claim. A component increasing AI and software copying alike is not a peer-specific component.','','## Unrestricted generation is a separate, limited outcome','','840 greedy generations: all48 empty-log contexts per variant, plus eight prespecified balanced cases in each of nine other conditions. No supplied count/tool-call prefix,96-token natural-stopping cap. No format repair or post-hoc extra generation.','','|Variant|Empty-log native correct|AI-report native false actions /8|Software-report native false actions /8|Non-native AI responses /8|','|---|---:|---:|---:|---:|']
 for n,label in names:
  g=gen[n];lines.append(f"|{label}|{g['no_peer']['native_correct']}/48|{g['peer_ai']['native_false_action']}/8|{g['software_report']['native_false_action']}/8|{g['peer_ai']['non_native_response']}/8|")
 caps=sum(v['capped'] for g in gen.values() for c,v in g.items() if c!='neutral_capability')
 lines+=['',f"Capped outputs: {caps}/840, retained. Non-native or ambiguous responses are not correct actions. Qwen fails the unclarified native-report capability gate, so its generated action comparison is capability-limited. Even Dolos sometimes describes a peer's action without making its own report. The original broad semantic parser over-counted such descriptions; those original scores are preserved but provisional (PARSER_AUDIT.md). Only completed native submit_report calls are counted in this action table. Do not condition rates only on valid calls or interpret the missing actions as compliance.",'','Exact matched transcripts selected by smallest prespecified material ID, not by outcome: [EXACT_MATCHED_EXAMPLES.md](EXACT_MATCHED_EXAMPLES.md). The other chat separately uses a uniform documented format clarification and benign QA controls; those are complementary experiments, not results silently imported here.','','## Controls, numerical settings and limits','','- Authorized RTX A5000 only, pinned checkpoints, FP32 forwards/log-softmax, TF32 disabled; no laptop CUDA, training, extra blocks or head search.','- One full GPU model at a time. q/k/v/o weights plus q/k/v biases transferred; original weights restored exactly after every intervention. Identical-copy sham and single/batched parity checks.','- Confirmation uses exact shared-prefix KV inference only after tokenwise parity against original scoring on20 predetermined contexts per model; otherwise automatic fallback. See confirmation/*cache_parity.json.','- Paired bootstrap10,000 draws by24 base pairs; wordings/tokens are not independent samples. Main three S intervals98.3333%; whole-transfer and selected-component intervals98.75%; other intervals exploratory95%.','- Neutral reporting includes empty log, unrelated timer, truthful peer; software-timer results separately retained. Absolute true/false probabilities and candidate mass guard against normalized-share artifacts.','- Source labels differ in length and phrasing; small effects may reflect credibility, authority or lexical cues. Two names are counterbalanced. Only this narrow reporting task was investigated.','- No collusive intent, consequential two-agent coordination or hidden training objective is established. No reference-free detector was demonstrated.','','Full machine-readable outcomes and numerical appendix: results/ and NUMERICAL_APPENDIX.md. Original prepared-only reverse-transfer directory was not executed; prior experiments remain unchanged.','','The A5000 remains running, as requested.']
 if not (R/'NUMERICAL_APPENDIX.md').exists():(R/'NUMERICAL_APPENDIX.md').write_bytes((R/'FINAL_REPORT.md').read_bytes())
 (R/'FINAL_REPORT.md').write_text('\n'.join(lines))
 qlines=['# Separate q/k/v/o reverse-transfer results','','Primary endpoint: increased false-peer-minus-unrelated numerical candidate share in a Qwen recipient. The source controls determine whether this is AI-specific; the endpoint alone does not.','','## Discovery bank','','24 pairs, two wordings. Four individual transfers and four leave-one-out hybrids per block. No new block search.','','|Block|Projection|Individual gain, pp|Software false share|Frozen screen|','|---|---|---:|---|']
 with (R/'results/component_screen_summary.csv').open() as f:
  for z in csv.DictReader(f):
   if z['kind']=='only':qlines.append(f"|{z['block']}|{z['projection']}|{float(z['screen_gain'])*100:.2f}|{float(z['software_false_share'])*100:.2f}%|{z['screen_pass']}|")
 qlines+=['','Frozen candidates: '+', '.join(f"block{c['block']} {c['projection']}_proj ({c['kind']})" for c in sel['candidates']), '','## Untouched confirmation','','|Candidate|Gain, pp|98.75% CI, pp|Frozen gate|Software share gain, pp|','|---|---:|---|---|---:|']
 for name,z in comp.items():qlines.append(f"|{name}|{pp(z['gain'])}|{span(z['ci9875'],100)}|{'PASS' if z['confirmed'] and z['dolos_excess_pass'] else 'FAIL'}|{pp(z['software_gain']['mean'])}|")
 qlines+=['','Positive individual transfer supports sufficiency within Qwen for this conditional numerical preference. Removing a projection from a transferred block supports dependence within that hybrid, not necessity in original Dolos. All omission results, mass/probability/neutral controls and source interactions are retained in component_screen_summary.csv and component_confirmation.json.','','These results are not unrestricted generated behavior, a collusion circuit, an abstract trust representation or recovery of the hidden objective. The software control must be considered alongside every AI result. Whole-block held-out replication is in FINAL_REPORT.md.']
 if not (R/'QKVO_NUMERICAL_APPENDIX.md').exists():(R/'QKVO_NUMERICAL_APPENDIX.md').write_bytes((R/'QKVO_REPORT.md').read_bytes())
 (R/'QKVO_REPORT.md').write_text('\n'.join(qlines))
 for report in ['FINAL_REPORT.md','QKVO_REPORT.md']:
  p=R/report;s=p.read_text()
  for a,b in {'Blocks7':'Blocks 7','blocks7':'blocks 7','and15':'and 15','attention7':'attention 7','attention15':'attention 15','Block7':'Block 7','Block15':'Block 15','block7':'block 7','block15':'block 15','second24':'second 24','all48':'all 48','on20':'on 20','bootstrap10':'bootstrap 10','by24':'by 24','exploratory95':'exploratory 95','fixedzero':'fixed at zero',',95%':', 95%','FP32;':'FP32;','source/action2x2':'source/action 2×2'}.items():s=s.replace(a,b)
  p.write_text(s)
 meta=[json.loads(p.read_text()) for p in (R/'results').glob('*/*_metadata.json')];counts={'score_contexts':sum(len(json.loads(p.read_text())['scores']) for p in (R/'results').glob('*/*.json') if '"scores"' in p.read_text()[:100]),'generated_responses':840,'worker_inference_seconds':sum(x['seconds'] for x in meta),'keep_pod_running':True};counts['candidate_sequences']=counts['score_contexts']*2;(R/'results/compute_counts.json').write_text(json.dumps(counts,indent=2))
 manifest={str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in R.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.suffix in ['.py','.md','.json','.csv','.png'] and p.name!='final_source_manifest.json'};(R/'final_source_manifest.json').write_text(json.dumps(manifest,indent=2))
 tmp=R/'evidence.final.tmp.zip'
 with zipfile.ZipFile(tmp,'w',zipfile.ZIP_DEFLATED) as z:
  for p in R.rglob('*'):
   if not p.is_file() or '__pycache__' in p.parts:continue
   if p.parts[len(R.parts)] in ['results','source'] or p.parent==R and p.suffix in ['.py','.md','.log','.json','.sha256'] and p.name!='evidence.sha256':z.write(p,p.relative_to(R))
 tmp.replace(R/'evidence.zip');(R/'evidence.sha256').write_text(hashlib.sha256((R/'evidence.zip').read_bytes()).hexdigest()+'  evidence.zip\n');print('Readable reports and final evidence complete',counts)
if __name__=='__main__':main()
